package com.example.rokidkeyboardbridge;
import android.content.*;import android.os.*;import android.widget.*;import android.view.*;import org.json.*;import java.lang.reflect.*;
/** Candidate receipt -> unchanged-geometry delta -> overview view, with synthetic packets only. */
public final class OverviewLiveTest {
 static int checks;static void ok(boolean v,String message){checks++;if(!v)throw new AssertionError(message);}static Field f(Class<?> c,String name)throws Exception{Field x=c.getDeclaredField(name);x.setAccessible(true);return x;}static void set(Object target,String key,Object value)throws Exception{f(MainActivity.class,key).set(target,value);}static void call(Object target,String key)throws Exception{Method m=MainActivity.class.getDeclaredMethod(key);m.setAccessible(true);m.invoke(target);}
 public static int run(Context c,String apk)throws Exception{checks=0;NavigationOverviewView view=new NavigationOverviewView(c);TextView text=(TextView)f(NavigationOverviewView.class,"live").get(view);ScrollView scroll=new ScrollView(c);scroll.addView(view);MainActivity owner=new MainActivity();Method attach=ContextWrapper.class.getDeclaredMethod("attachBaseContext",Context.class);attach.setAccessible(true);attach.invoke(owner,c);set(owner,"navigationOverviewView",view);set(owner,"navigationOverviewScroll",scroll);NavigationGeometryDelta.Encoder encoder=new NavigationGeometryDelta.Encoder();NavigationGeometryDelta.Decoder decoder=new NavigationGeometryDelta.Decoder();long now=System.currentTimeMillis(),elapsed=SystemClock.elapsedRealtime();
 for(String mode:new String[]{"walking","bicycling","driving","transit"})for(int i=0;i<50;i++){JSONObject packet=new JSONObject().put("source","google").put("routeMode",mode).put("routeDestination","合成目的地").put("routeTime",1000).put("routeGeneration",1).put("navigationActive",true).put("routeReady",true).put("time",now).put("locationTime",now).put("instruction","合成案内"+i).put("detail","区間"+i).put("totalRemainingDuration",(50-i)+"分").put("totalRemainingDistance",(500-i)+" m").put("routeArrival","11:"+String.format("%02d",i)).put("route",new JSONArray("[[0,0],[0,0.01]]")).put("journey",new JSONObject().put("requestedMode",mode).put("finalDestination","合成目的地").put("overviewSummary",new JSONObject().put("durationSeconds",3600).put("distanceMeters",10000).put("arrivalTime","2026-10-24T03:00:00Z")));JSONObject transported=encoder.encode(packet,decoder.known());if(i>0)ok(!transported.getJSONObject("navigationDelta").has("parts"),"same route geometry retransmitted");JSONObject received=decoder.decode(new JSONObject(transported.toString()));ok(received.getJSONArray("route").length()==2,"delta geometry lost");NavigationOverviewSummary summary=NavigationOverviewSummary.from(received);ok(summary.duration.equals("約60分")&&summary.distance.equals("10.0km"),"whole-route totals replaced with remaining values");view.bind(summary);NavigationOverviewLive live=new NavigationOverviewLive(received,now,elapsed);set(owner,"navigationOverviewLiveData",live);call(owner,"refreshNavigationOverviewLive");String shown=text.getText().toString();ok(shown.contains("合成案内"+i),"new instruction missing");ok(shown.contains((50-i)+"分")&&shown.contains((500-i)+" m"),"remaining values did not update");ok(shown.contains("11:"+String.format("%02d",i)),"live ETA did not update");ok(live.render(elapsed+16000,false).contains("前回の情報"),"stale receipt shown as live");ok(live.render(elapsed,true).contains("更新待ち"),"failed link hidden by overview");ok(live.render(elapsed-1,false).contains("前回の情報"),"clock reversal accepted");}
 JSONObject healthy=new JSONObject().put("time",now).put("locationTime",now).put("routeReady",true).put("instruction","復帰後の案内").put("totalRemainingDuration","3分").put("routeArrival","12:34");set(owner,"navigationOverviewLiveData",new NavigationOverviewLive(healthy,now,SystemClock.elapsedRealtime()));set(owner,"navigationReceiveFailure",true);call(owner,"refreshNavigationOverviewLive");ok(text.getText().toString().contains("前回の情報"),"failure callback did not update visible panel");set(owner,"navigationReceiveFailure",false);call(owner,"refreshNavigationOverviewLive");ok(!text.getText().toString().contains("前回の情報")&&text.getText().toString().contains("復帰後"),"reconnect did not restore live guidance");ok(new NavigationOverviewLive(new JSONObject(healthy.toString()).put("locationTime",0),now,elapsed).render(elapsed,false).contains("位置情報の更新待ち"),"GPS loss hidden");ok(new NavigationOverviewLive(new JSONObject(healthy.toString()).put("guidancePaused",true),now,elapsed).render(elapsed,false).contains("一時停止"),"pause hidden");ok(new NavigationOverviewLive(new JSONObject(healthy.toString()).put("routeRefreshing",true),now,elapsed).render(elapsed,false).contains("経路を更新中"),"reroute hidden");ok(new NavigationOverviewLive(new JSONObject(healthy.toString()).put("time",now-90001),now,elapsed).render(elapsed,false).contains("前回の情報"),"old phone data accepted");ok(new NavigationOverviewLive(new JSONObject(),now,elapsed).render(elapsed,false).contains("未取得"),"unknown values invented");
 Class<?> mapClass=f(MainActivity.class,"navigationMap").getType();Constructor<?> ctor=mapClass.getDeclaredConstructor(MainActivity.class,Context.class);ctor.setAccessible(true);Object map=ctor.newInstance(owner,c);Method overview=mapClass.getDeclaredMethod("setOverview",boolean.class);overview.setAccessible(true);overview.invoke(map,true);Method position=mapClass.getDeclaredMethod("setLocation",double.class,double.class,float.class,float.class,float.class,long.class);position.setAccessible(true);position.invoke(map,0d,0d,0f,1f,5f,now);position.invoke(map,0d,.001d,10f,2f,5f,now+1000);ok(f(mapClass,"longitude").getDouble(map)==.001d,"overview position did not advance");ok(f(mapClass,"locationSampleTime").getLong(map)==now+1000,"overview location time frozen");overview.invoke(map,false);overview.invoke(map,true);position.invoke(map,0d,.002d,20f,2f,5f,now+2000);ok(f(mapClass,"longitude").getDouble(map)==.002d,"mode round trip froze position");
 c.getSharedPreferences("navigation_display",0).edit().putBoolean("large_map",true).putBoolean("overview",true).commit();set(owner,"activityForeground",true);set(owner,"startupNavigationBlocked",false);set(owner,"navigationHudSuppressed",false);LinearLayout panel=new LinearLayout(c);set(owner,"navigationPanel",panel);set(owner,"mapNavigationActive",true);Method screen=MainActivity.class.getDeclaredMethod("isActiveFollowNavigation");screen.setAccessible(true);ok((Boolean)screen.invoke(owner),"active overview excluded from screen update policy");set(owner,"mapNavigationActive",false);ok(!(Boolean)screen.invoke(owner),"inactive overview keeps screen awake");set(owner,"mapNavigationActive",true);set(owner,"activityForeground",false);ok(!(Boolean)screen.invoke(owner),"background overview keeps screen awake");
 return checks+CommentStatusTest.run(c,apk);}
}
